#!/usr/bin/env python3
"""Read-only Cursor storage inventory scanner."""
import json
import os
import re
import sqlite3
from collections import Counter, defaultdict
from datetime import datetime
from pathlib import Path

USER = Path("C:/Users/win")
DATE_FMT = "%Y-%m-%d"


def fmt_size(n):
    if n is None or n == 0:
        return "0 B"
    for u, div in [("GB", 1 << 30), ("MB", 1 << 20), ("KB", 1 << 10)]:
        if n >= div:
            return f"{n / div:.2f} {u}"
    return f"{n} B"


def dir_stats(root: Path, pattern="*", recursive=True):
    if not root.exists():
        return {"exists": False, "files": 0, "size": 0, "earliest": None, "latest": None}
    files = list(root.rglob(pattern) if recursive else root.glob(pattern))
    files = [f for f in files if f.is_file()]
    if not files:
        return {"exists": True, "files": 0, "size": 0, "earliest": None, "latest": None}
    mtimes = [f.stat().st_mtime for f in files]
    sizes = sum(f.stat().st_size for f in files)
    return {
        "exists": True,
        "files": len(files),
        "size": sizes,
        "earliest": datetime.fromtimestamp(min(mtimes)).strftime(DATE_FMT),
        "latest": datetime.fromtimestamp(max(mtimes)).strftime(DATE_FMT),
    }


def scan_transcripts():
    proj_root = USER / ".cursor/projects"
    results = []
    all_jsonl = []
    if not proj_root.exists():
        return results, all_jsonl
    for proj_dir in sorted(proj_root.iterdir()):
        if not proj_dir.is_dir():
            continue
        at_dir = proj_dir / "agent-transcripts"
        if not at_dir.exists():
            continue
        jsonl_files = list(at_dir.rglob("*.jsonl"))
        if not jsonl_files:
            continue
        parent_sessions = [f for f in jsonl_files if f.parent.name != "subagents"]
        subagent_files = [f for f in jsonl_files if "subagents" in f.parts]
        mtimes = [f.stat().st_mtime for f in jsonl_files]
        sizes = sum(f.stat().st_size for f in jsonl_files)
        results.append({
            "project_key": proj_dir.name,
            "path": str(at_dir),
            "total_jsonl": len(jsonl_files),
            "parent_sessions": len(parent_sessions),
            "subagent_files": len(subagent_files),
            "size": sizes,
            "earliest": datetime.fromtimestamp(min(mtimes)).strftime(DATE_FMT),
            "latest": datetime.fromtimestamp(max(mtimes)).strftime(DATE_FMT),
        })
        all_jsonl.extend(jsonl_files)
    return results, all_jsonl


def scan_vscdb():
    bases = [
        USER / "AppData/Roaming/Cursor",
        USER / "AppData/Local/Cursor",
    ]
    found = []
    for base in bases:
        if not base.exists():
            continue
        for p in base.rglob("state.vscdb*"):
            if p.is_file():
                st = p.stat()
                found.append({
                    "path": str(p),
                    "size": st.st_size,
                    "mtime": datetime.fromtimestamp(st.st_mtime).strftime(DATE_FMT),
                })
    return found


def peek_vscdb_keys(db_path: Path, limit=30):
    """Sample keys from state.vscdb without reading values (may contain secrets)."""
    keys = []
    try:
        conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
        cur = conn.cursor()
        for table in ("ItemTable", "cursorDiskKV"):
            try:
                cur.execute(f"SELECT key FROM {table} LIMIT ?", (limit,))
                keys.extend([(table, r[0]) for r in cur.fetchall()])
            except sqlite3.Error:
                pass
        conn.close()
    except sqlite3.Error as e:
        keys = [("error", str(e))]
    return keys


def scan_workspace_storage():
    results = []
    for base_name in ("Roaming", "Local"):
        ws = USER / f"AppData/{base_name}/Cursor/User/workspaceStorage"
        if not ws.exists():
            continue
        dirs = [d for d in ws.iterdir() if d.is_dir()]
        total_size = sum(f.stat().st_size for f in ws.rglob("*") if f.is_file())
        mtimes = [f.stat().st_mtime for d in dirs for f in d.rglob("*") if f.is_file()]
        results.append({
            "base": str(ws),
            "workspace_count": len(dirs),
            "total_size": total_size,
            "earliest": datetime.fromtimestamp(min(mtimes)).strftime(DATE_FMT) if mtimes else None,
            "latest": datetime.fromtimestamp(max(mtimes)).strftime(DATE_FMT) if mtimes else None,
        })
    return results


def scan_desktop_projects():
    desktop = USER / "Desktop"
    if not desktop.exists():
        return []
    return sorted([p.name for p in desktop.iterdir() if p.is_dir()])


def find_project_memory(desktop_projects):
    hits = []
    search_roots = [USER / "Desktop"]
    for root in search_roots:
        if not root.exists():
            continue
        for mem in root.rglob(".github/agent/memory"):
            if mem.is_dir():
                rel = mem.relative_to(root)
                hits.append(str(mem))
        for cur in root.rglob(".cursor"):
            if cur.is_dir() and cur.name == ".cursor":
                # only top-level project .cursor
                if cur.parent.name in desktop_projects or "Desktop" in str(cur):
                    hits.append(str(cur))
    return hits[:50]


def read_memory_meta(path: Path):
    st = path.stat()
    return {
        "path": str(path),
        "size": st.st_size,
        "mtime": datetime.fromtimestamp(st.st_mtime).strftime(DATE_FMT),
    }


def count_lines_dates_in_file(path: Path, max_lines=5):
    """Sample first lines for date hints, no content dump."""
    try:
        with open(path, "r", encoding="utf-8", errors="replace") as f:
            lines = []
            for i, line in enumerate(f):
                if i >= max_lines:
                    break
                lines.append(line.strip()[:120])
        return lines
    except OSError:
        return []


def main():
    out = {}

    # 1. Transcripts
    transcript_projects, all_jsonl = scan_transcripts()
    out["transcript_projects"] = transcript_projects
    if all_jsonl:
        mtimes = [f.stat().st_mtime for f in all_jsonl]
        out["transcript_totals"] = {
            "projects_with_transcripts": len(transcript_projects),
            "total_jsonl": len(all_jsonl),
            "total_size": sum(f.stat().st_size for f in all_jsonl),
            "earliest": datetime.fromtimestamp(min(mtimes)).strftime(DATE_FMT),
            "latest": datetime.fromtimestamp(max(mtimes)).strftime(DATE_FMT),
        }
    else:
        out["transcript_totals"] = {"projects_with_transcripts": 0, "total_jsonl": 0}

    # Sample transcript structure (metadata only)
    sample = None
    for f in all_jsonl[:1]:
        try:
            with open(f, "r", encoding="utf-8", errors="replace") as fh:
                first = fh.readline()
                if first:
                    obj = json.loads(first)
                    sample = {k: type(v).__name__ for k, v in obj.items()}
        except (json.JSONDecodeError, OSError):
            sample = {"error": "unreadable"}
    out["transcript_sample_schema"] = sample

    # 2. Rules & skills
    for name in ("rules", "skills"):
        p = USER / f".cursor/{name}"
        out[f"cursor_{name}"] = dir_stats(p)

    # skills-cursor
    sc = USER / ".cursor/skills-cursor"
    out["cursor_skills_cursor"] = dir_stats(sc) if sc.exists() else {"exists": False}

    # 3. ai-workspace memory
    mem_dir = USER / ".ai-workspace/memory"
    key_files = [
        "global-task-history.md",
        "user-memory.md",
        "projects-registry.md",
        "global-decisions-log.md",
        "global-agent-master.md",
    ]
    out["ai_workspace_memory"] = {"dir_stats": dir_stats(mem_dir)}
    out["ai_workspace_key_files"] = {}
    for kf in key_files:
        fp = mem_dir / kf
        if fp.exists():
            out["ai_workspace_key_files"][kf] = read_memory_meta(fp)

    # 4. vscdb
    out["vscdb_files"] = scan_vscdb()
    # peek largest vscdb keys only
    if out["vscdb_files"]:
        largest = max(out["vscdb_files"], key=lambda x: x["size"])
        lp = Path(largest["path"])
        out["vscdb_largest_sample_keys"] = {
            "path": largest["path"],
            "keys": peek_vscdb_keys(lp, 40),
        }

    out["workspace_storage"] = scan_workspace_storage()

    # globalStorage cursor-related
    gs_items = []
    for base_name in ("Roaming", "Local"):
        gs = USER / f"AppData/{base_name}/Cursor/User/globalStorage"
        if gs.exists():
            for d in gs.iterdir():
                if d.is_dir():
                    sz = sum(f.stat().st_size for f in d.rglob("*") if f.is_file())
                    mt = max((f.stat().st_mtime for f in d.rglob("*") if f.is_file()), default=0)
                    gs_items.append({
                        "id": d.name,
                        "base": base_name,
                        "size": sz,
                        "latest": datetime.fromtimestamp(mt).strftime(DATE_FMT) if mt else None,
                    })
    out["global_storage"] = sorted(gs_items, key=lambda x: -x["size"])[:25]

    # 5. Desktop projects & project keys from cursor projects
    desktop_dirs = scan_desktop_projects()
    out["desktop_dirs"] = desktop_dirs

    proj_keys = [p["project_key"] for p in transcript_projects]
    # decode project keys: c-Users-win-Desktop-XXX -> Desktop/XXX
    decoded = Counter()
    for pk in proj_keys:
        m = re.match(r"c-Users-win-Desktop(?:-(.+))?", pk)
        if m:
            name = m.group(1).replace("-", " ") if m.group(1) else "(Desktop root)"
            decoded[name] += 1
        else:
            decoded[pk] += 1
    out["transcript_project_decode"] = decoded.most_common(30)

    # All cursor project dirs
    proj_root = USER / ".cursor/projects"
    if proj_root.exists():
        out["all_cursor_project_dirs"] = sorted([d.name for d in proj_root.iterdir() if d.is_dir()])

    # 6. Other cursor dirs
    for sub in ("plans", "snapshots", "chats", "browser-logs", "ai-tracking"):
        p = USER / f".cursor/{sub}"
        if p.exists():
            out[f"cursor_{sub}"] = dir_stats(p)

    # .claude memory overlap
    claude_mem = USER / ".claude"
    if claude_mem.exists():
        out["claude_dir"] = dir_stats(claude_mem)
        out["claude_agents_md"] = read_memory_meta(claude_mem / "AGENTS.md") if (claude_mem / "AGENTS.md").exists() else None

    # codex
    codex = USER / ".codex"
    if codex.exists():
        out["codex_dir"] = dir_stats(codex)

    # projects-registry project paths (grep paths only)
    reg = mem_dir / "projects-registry.md"
    if reg.exists():
        paths = re.findall(r"C:/Users/win[^\s`|]+", reg.read_text(encoding="utf-8", errors="replace"))
        out["projects_registry_paths"] = paths[:40]

    print(json.dumps(out, indent=2, ensure_ascii=False, default=str))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
import json
import sqlite3
from datetime import datetime
from pathlib import Path

USER = Path("C:/Users/win")


def scan_vscdb_keys():
    db = USER / "AppData/Roaming/Cursor/User/globalStorage/state.vscdb"
    out = {}
    conn = sqlite3.connect(f"file:{db}?mode=ro", uri=True)
    cur = conn.cursor()
    patterns = ("chat", "composer", "conversation", "aichat", "cursorChat", "bubble", "agent", "history")
    for table in ("ItemTable", "cursorDiskKV"):
        try:
            cur.execute(f"SELECT key FROM {table}")
            keys = [r[0] for r in cur.fetchall()]
            matched = [k for k in keys if any(p.lower() in k.lower() for p in patterns)]
            out[table] = {"total": len(keys), "matched": len(matched), "sample": sorted(matched)[:50]}
        except sqlite3.Error as e:
            out[table] = {"error": str(e)}
    conn.close()
    return out


def scan_workspace_storage():
    ws = USER / "AppData/Roaming/Cursor/User/workspaceStorage"
    rows = []
    for d in sorted(ws.iterdir()):
        if not d.is_dir():
            continue
        wj = d / "workspace.json"
        folder = None
        if wj.exists():
            try:
                data = json.loads(wj.read_text(encoding="utf-8"))
                folder = data.get("folder") or data.get("configuration", {}).get("folder")
            except (json.JSONDecodeError, OSError):
                folder = "parse_error"
        files = [f for f in d.rglob("*") if f.is_file()]
        sz = sum(f.stat().st_size for f in files)
        mt = max((f.stat().st_mtime for f in files), default=0)
        vscdb = d / "state.vscdb"
        vscdb_sz = vscdb.stat().st_size if vscdb.exists() else 0
        rows.append({
            "id": d.name,
            "folder": folder,
            "total_kb": sz // 1024,
            "vscdb_kb": vscdb_sz // 1024,
            "latest": datetime.fromtimestamp(mt).strftime("%Y-%m-%d") if mt else None,
        })
    return rows


def scan_project_memory_on_desktop():
    desktop = USER / "Desktop"
    hits = []
    for proj in sorted(desktop.iterdir()):
        if not proj.is_dir():
            continue
        mem = proj / ".github/agent/memory"
        cur = proj / ".cursor"
        entry = {"project": proj.name, "memory_files": 0, "memory_kb": 0, "cursor_files": 0, "cursor_kb": 0}
        if mem.exists():
            files = [f for f in mem.rglob("*") if f.is_file()]
            entry["memory_files"] = len(files)
            entry["memory_kb"] = sum(f.stat().st_size for f in files) // 1024
            entry["memory_path"] = str(mem)
        if cur.exists():
            files = [f for f in cur.rglob("*") if f.is_file()]
            entry["cursor_files"] = len(files)
            entry["cursor_kb"] = sum(f.stat().st_size for f in files) // 1024
            entry["cursor_path"] = str(cur)
        if entry["memory_files"] or entry["cursor_files"]:
            hits.append(entry)
    return hits


def count_parent_sessions():
    root = USER / ".cursor/projects"
    sessions = []
    for at in root.glob("*/agent-transcripts"):
        for p in at.iterdir():
            if p.is_dir() and p.name != "subagents":
                main = p / f"{p.name}.jsonl"
                if main.exists():
                    st = main.stat()
                    sessions.append({
                        "project": at.parent.name,
                        "session_id": p.name[:8],
                        "kb": st.st_size // 1024,
                        "mtime": datetime.fromtimestamp(st.st_mtime).strftime("%Y-%m-%d"),
                    })
    sessions.sort(key=lambda x: x["mtime"])
    return {"count": len(sessions), "earliest": sessions[0] if sessions else None, "latest": sessions[-1] if sessions else None}


if __name__ == "__main__":
    result = {
        "vscdb_keys": scan_vscdb_keys(),
        "workspace_storage": scan_workspace_storage(),
        "desktop_project_memory": scan_project_memory_on_desktop(),
        "parent_sessions": count_parent_sessions(),
    }
    print(json.dumps(result, indent=2, ensure_ascii=False))
